import { Injectable, computed, inject } from '@angular/core';
import { Claim, ClaimShare, Claims, bound, countsAt, isOpen, partCents, statusAt } from './claims';
import { CrewView, Crews } from './crews';
import { People, Person, gradeOn } from './people';
import { Period, Periods } from './periods';
import { Pools } from './pools';
import { NO_RATE, Rates, halfEven, hundredths, money, rounded } from './rates';
import { Roles } from './roles';
import { Session, addDays } from './session';

/** The statuses claims are counted by, in the order the screen shows them. */
export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'] as const;

/** People's figures added up, leaving out the single highest and the single lowest when there are
 *  three or more. */
export function trimmed(figures: bigint[]): bigint {
  const sum = figures.reduce((s, f) => s + f, 0n);
  if (figures.length < 3) return sum;
  const max = figures.reduce((m, f) => (f > m ? f : m));
  const min = figures.reduce((m, f) => (f < m ? f : m));
  return sum - max - min;
}

// The due figures the screen shows, worked out in one place so the people list, the periods list,
// the summary and the header always agree.
@Injectable({ providedIn: 'root' })
export class Figures {
  private readonly claims = inject(Claims);
  private readonly crews = inject(Crews);
  private readonly people = inject(People);
  private readonly periods = inject(Periods);
  private readonly pools = inject(Pools);
  private readonly rates = inject(Rates);
  private readonly roles = inject(Roles);
  private readonly session = inject(Session);

  /** A person's due-total: the sum of their figures, at most the sheet's cap less their cut total (not below
   *  0.00). Null (n/a) is not capped. */
  dueCents(p: Person): bigint | null {
    const sum = this.sumCents(p);
    const cap = this.capCents(p);
    return sum !== null && cap !== null && sum > cap ? cap : sum;
  }

  /** How far the sum of a person's figures is above the sheet's cap less their cut total; 0 when it is not
   *  (or is n/a). */
  excessCents(p: Person): bigint {
    const sum = this.sumCents(p);
    const cap = this.capCents(p);
    return sum !== null && cap !== null && sum > cap ? sum - cap : 0n;
  }

  /** The most a person's due-total can be: the sheet's cap less their cut total, not below 0.00; null for no cap. */
  private capCents(p: Person): bigint | null {
    const cap = this.session.cap();
    if (cap === null) return null;
    const left = hundredths(cap) - (this.pools.cutCents().get(p.id) ?? 0n);
    return left > 0n ? left : 0n;
  }

  /** The sum of the figures of a person's claims that count live (not left out by a hold), less the parts others
   *  hold of them, and the parts they hold of other people's: a settled claim's frozen due, else the
   *  figure their last statement bound it to, else its live due at the rate in force on its date (a
   *  claim with no figure adds nothing). Null when the grade in force on the sheet's today has no rate
   *  there and no claim has a figure. */
  sumCents(p: Person): bigint | null {
    let sum = 0n;
    let keptFigure = false;
    for (const c of this.claims.live().filter((c) => c.personId === p.id)) {
      if (c.settledDue !== null || (bound(c) && c.statedDue !== null)) keptFigure = true;
      // a claim priced at the grade in force on its date keeps a figure too
      else if (!bound(c) && this.rates.inForceFor(gradeOn(p.grades, c.date), c.date, c.id) !== undefined) keptFigure = true;
      sum += this.ownCents(c, p);
    }
    for (const { c, part, priced } of this.heldParts(p)) {
      // a part of a claim with a figure, priced at the holder's rate (or frozen), keeps a figure too
      if (priced && this.hasFigure(c)) keptFigure = true;
      sum += part;
    }
    const today = this.session.shownToday();
    const rated = today ? this.rates.inForce(gradeOn(p.grades, today), today) !== undefined : false;
    return rated || keptFigure ? sum : null;
  }

  /** A claim's figure less the parts its holders hold of it: what its own person counts of it. */
  ownCents(c: Claim, p: Person): bigint {
    const due = this.figureCents(c, p);
    return (c.shares ?? []).reduce((rest, s) => rest - (this.partOf(c, s, due) ?? 0n), due);
  }

  /** The parts a person holds of other people's claims that count live, each with its claim (see `partOf`). */
  heldParts(p: Person): { c: Claim; part: bigint; priced: boolean }[] {
    const parts: { c: Claim; part: bigint; priced: boolean }[] = [];
    for (const c of this.claims.live()) {
      const held = (c.shares ?? []).find((s) => s.personId === p.id);
      const owner = held && this.people.people().find((o) => o.id === c.personId);
      if (!held || !owner) continue;
      const part = this.partOf(c, held, this.figureCents(c, owner));
      parts.push({ c, part: part ?? 0n, priced: part !== null });
    }
    return parts;
  }

  /** A holder's part of a claim, in cents: its amount times their share divided by 100, times the rate of the
   *  holder's own grade in force on its date divided by 100, rounded as the claim rounds; null (counting as 0)
   *  when their grade has no rate then. A settled claim keeps its parts as frozen: its figure times the share divided by 100,
   *  rounded half to even. */
  private partOf(c: Claim, s: ClaimShare, figureCents: bigint): bigint | null {
    if (c.settledDue !== null) return partCents(figureCents, s.share);
    const holder = this.people.people().find((o) => o.id === s.personId);
    const rate = holder && this.rates.inForceFor(gradeOn(holder.grades, c.date), c.date, c.id);
    if (!rate) return null;
    const roundOn = this.claims.roundingDate(c);
    return rounded(hundredths(c.amount) * hundredths(s.share) * hundredths(rate.rate), 100000000n,
      this.session.roundsHalfUp(roundOn));
  }

  /** Whether a claim has a figure: settled, bound to one, or priced at the grade in force on its date. */
  private hasFigure(c: Claim): boolean {
    if (c.settledDue !== null) return true;
    if (bound(c)) return c.statedDue !== null;
    const owner = this.people.people().find((o) => o.id === c.personId);
    return owner !== undefined && this.rates.inForceFor(gradeOn(owner.grades, c.date), c.date, c.id) !== undefined;
  }

  /** The due of a person's SETTLED claims that count live, at their frozen figures, corrections included, less
   *  the parts others hold of them, and the parts they hold of other people's. */
  settledCents(p: Person): bigint {
    const own = this.claims
      .live()
      .filter((c) => c.personId === p.id && c.status === 'SETTLED')
      .reduce((sum, c) => sum + this.ownCents(c, p), 0n);
    return this.heldParts(p).filter(({ c }) => c.status === 'SETTLED').reduce((sum, { part }) => sum + part, own);
  }

  /** The due of a person's SETTLED claims that count live and correct nothing, at their frozen figures. */
  scoreSettledCents(p: Person): bigint {
    return this.claims
      .live()
      .filter((c) => c.personId === p.id && c.status === 'SETTLED' && !c.corrects)
      .reduce((sum, c) => sum + this.figureCents(c, p), 0n);
  }

  /** The due of a person's OPEN and PENDING claims that count live (not deferred or retired-and-excluded), less
   *  the parts others hold of them, and the parts they hold of other people's. */
  openCents(p: Person): bigint {
    const own = this.claims
      .live()
      .filter((c) => c.personId === p.id && isOpen(c))
      .reduce((sum, c) => sum + this.ownCents(c, p), 0n);
    return this.heldParts(p).filter(({ c }) => isOpen(c)).reduce((sum, { part }) => sum + part, own);
  }

  /** Everyone's settled-total added up (not trimmed). */
  readonly settledTotal = computed(() =>
    money(this.people.people().reduce((sum, p) => sum + this.settledCents(p), 0n)),
  );

  /** Everyone's open-total added up (not trimmed). */
  readonly openTotal = computed(() =>
    money(this.people.people().reduce((sum, p) => sum + this.openCents(p), 0n)),
  );

  /** Everyone's (capped) due-total added up, skipping those whose grade has no rate, trimmed. */
  readonly dueTotal = computed(() =>
    money(trimmed(this.people.people().map((p) => this.dueCents(p)).filter((d): d is bigint => d !== null))),
  );

  /** By grade (every grade, in order), the due-totals of the people on it today added up, retired people left
   *  out and a due-total of n/a adding nothing, as the summary shows them. */
  readonly gradeDueTotals = computed(() => {
    const current = this.people.people().filter((p) => !p.retired);
    return this.session.grades().map((grade) => ({
      grade,
      dueTotal: money(
        current.filter((p) => this.gradeToday(p) === grade).reduce((sum, p) => sum + (this.dueCents(p) ?? 0n), 0n),
      ),
    }));
  });

  /** The due of everyone's overdue claims that count, added up, trimmed. */
  readonly overdueTotal = computed(() =>
    money(trimmed(this.people.people().map((p) => this.overdueCents(p)))),
  );

  /** The person whose name or an alias is the signed-in user's name, compared as names are (trimmed,
   *  ignoring case); undefined when no one on the sheet has it. */
  private readonly me = computed(() => {
    const user = this.session.user()?.trim().toLowerCase();
    if (!user) return undefined;
    return this.people
      .people()
      .find((p) => p.name.trim().toLowerCase() === user || p.aliases.some((a) => a.trim().toLowerCase() === user));
  });

  /** The signed-in user's own figures: the due-total (n/a when it has none) and overdue-total of the
   *  person with the user's name; null when no one on the sheet has it. */
  readonly mine = computed(() => {
    const p = this.me();
    if (!p) return null;
    const due = this.dueCents(p);
    return { dueTotal: due === null ? NO_RATE : money(due), overdueTotal: money(this.overdueCents(p)) };
  });

  /** Whether the signed-in user is a steward on the sheet: given the role, or delegated it for the sheet's
   *  today (under an as-of date, the roles and delegations as they stood then). */
  private readonly steward = computed(() => {
    const user = this.session.user();
    const today = this.session.today();
    if (!user) return false;
    if (this.roles.roles().some((r) => r.user === user && r.role === 'steward')) return true;
    return today !== null && this.roles.delegations().some((d) => d.user === user && d.from <= today && today <= d.to);
  });

  /** The ids of the people a restricted user's people list shows: the person with the user's name,
   *  everyone in a crew they lead or belong to, and anyone they added on this screen until the sheet is
   *  loaded again; null when the signed-in user is not restricted (a user
   *  delegated the steward role acts as a steward). Every other figure is still over everyone. */
  readonly visibleIds = computed(() => {
    const user = this.session.user();
    if (!user || this.steward()) return null;
    if (!this.roles.roles().some((r) => r.user === user && r.role === 'restricted')) return null;
    const loaded = this.people.loadedIds();
    const ids = new Set<number>(this.people.people().filter((o) => !loaded.has(o.id)).map((o) => o.id));
    const p = this.me();
    if (!p) return ids;
    ids.add(p.id);
    for (const c of this.crews.crews()) {
      const crew = [...(c.lead ? [c.lead.personId] : []), ...c.members.map((m) => m.personId)];
      if (crew.includes(p.id)) crew.forEach((id) => ids.add(id));
    }
    return ids;
  });

  /** A steward's dashboard: the PENDING and REVIEW claims and the overdue claims that count of the sheet
   *  and all its descendants, counted; null when the signed-in user is not a steward. */
  readonly dashboard = computed(() => {
    if (!this.steward()) return null;
    const claims = this.claims.claims();
    const d = this.session.descendants();
    return {
      pending: claims.filter((c) => c.status === 'PENDING').length + (d.statusCounts['PENDING'] ?? 0),
      review: claims.filter((c) => c.status === 'REVIEW').length + (d.statusCounts['REVIEW'] ?? 0),
      overdue: this.claims.live().filter((c) => this.claims.overdue(c)).length + d.overdueCount,
    };
  });

  /** How many of the sheet's REVIEW claims are assigned to the signed-in user, names compared trimmed and
   *  without regard to case. */
  readonly myReviewsCount = computed(() => {
    const user = this.session.user()?.trim().toLowerCase();
    if (!user) return 0;
    return this.claims.claims().filter((c) => c.status === 'REVIEW' && c.reviewAssignee?.trim().toLowerCase() === user)
      .length;
  });

  /** A crew's due-total: the lead's and the members' due-totals as the people list shows them, added up,
   *  n/a skipped. */
  crewDueCents(c: CrewView): bigint {
    const ids = new Set([...(c.lead ? [c.lead.personId] : []), ...c.members.map((m) => m.personId)]);
    let sum = 0n;
    for (const p of this.people.people()) {
      if (!ids.has(p.id)) continue;
      const d = this.dueCents(p);
      if (d !== null) sum += d;
    }
    return sum;
  }

  /** The signed-in user's crew total: the due-totals of the crews the person with the user's name leads,
   *  added up; null when there is no such person or they lead no crew. */
